use crate::ai::agent_loop::{ToolDispatcher, ToolSpec};
use schemars::JsonSchema;
use serde::Serialize;
use serde::de::DeserializeOwned;
use std::future::Future;
use std::pin::Pin;

pub type BoxedToolFuture<'a> = Pin<Box<dyn Future<Output = (String, String)> + 'a>>;

/// Cleans up raw JSON schema values generated by `schemars` to ensure full compatibility
/// with OpenAI and Gemini function calling specifications.
pub fn clean_openai_parameters(mut val: serde_json::Value) -> serde_json::Value {
    if let serde_json::Value::Object(ref mut map) = val {
        // Remove meta-schema attributes that OpenAI / Gemini dislike
        map.remove("$schema");
        map.remove("title");

        // Ensure "type": "object" is explicitly present
        if !map.contains_key("type") {
            map.insert("type".to_string(), serde_json::json!("object"));
        }

        // Ensure "properties" exists even for empty argument structs
        if !map.contains_key("properties") {
            map.insert("properties".to_string(), serde_json::json!({}));
        }
    }
    val
}

/// Extracts the description from a type deriving `JsonSchema` doc comments.
pub fn description_from_schema<T: JsonSchema>() -> Option<String> {
    let raw = serde_json::to_value(schemars::schema_for!(T)).ok()?;
    raw.get("description")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string())
}

/// Generates a `ToolSpec` from a typed argument struct deriving `schemars::JsonSchema`.
/// If `override_desc` is `None`, extracts the doc comment from the struct definition.
pub fn spec_from_schema<T: JsonSchema>(name: &str, override_desc: Option<&str>) -> ToolSpec {
    let raw = serde_json::to_value(schemars::schema_for!(T)).unwrap_or_default();
    let description = override_desc
        .map(|s| s.to_string())
        .or_else(|| {
            raw.get("description")
                .and_then(|v| v.as_str())
                .map(|s| s.to_string())
        })
        .unwrap_or_else(|| format!("Execute {name}"));

    ToolSpec {
        name: name.to_string(),
        description,
        parameters: clean_openai_parameters(raw),
    }
}

/// An executable tool with its OpenAI-compatible spec and typed dispatch handler.
pub struct TypedTool {
    pub spec: ToolSpec,
    handler: Box<dyn Fn(&str) -> BoxedToolFuture<'_> + Send + Sync>,
}

impl TypedTool {
    /// Creates a new `TypedTool` from an argument type and an async execution handler.
    pub fn new<Args, F, Fut>(name: &'static str, description: Option<&str>, handler: F) -> Self
    where
        Args: JsonSchema + DeserializeOwned + 'static,
        F: Fn(Args) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = (String, String)> + 'static,
    {
        let spec = spec_from_schema::<Args>(name, description);
        Self {
            spec,
            handler: Box::new(move |raw_json: &str| {
                let parsed = serde_json::from_str::<Args>(raw_json);
                match parsed {
                    Ok(args) => Box::pin(handler(args)),
                    Err(err) => Box::pin(async move {
                        let msg = format!("Invalid arguments for tool '{name}': {err}");
                        (msg.clone(), msg)
                    }),
                }
            }),
        }
    }

    /// Executes the tool with the raw JSON string received from the LLM.
    pub async fn execute(&self, raw_json: &str) -> (String, String) {
        (self.handler)(raw_json).await
    }
}

/// A registry of typed tools that automatically derives `ToolSpec`s for LLM prompts
/// and implements `ToolDispatcher` for generic execution.
#[derive(Default)]
pub struct ToolRegistry {
    tools: Vec<TypedTool>,
}

impl ToolRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn register(&mut self, tool: TypedTool) {
        self.tools.push(tool);
    }

    /// Registers a tool function where the description is automatically extracted
    /// from the `Args` struct doc comments.
    pub fn register_fn<Args, F, Fut>(&mut self, name: &'static str, handler: F)
    where
        Args: JsonSchema + DeserializeOwned + 'static,
        F: Fn(Args) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = (String, String)> + 'static,
    {
        self.register(TypedTool::new::<Args, _, _>(name, None, handler));
    }

    /// Registers a tool function with an explicit description override.
    pub fn register_with_desc<Args, F, Fut>(
        &mut self,
        name: &'static str,
        description: &'static str,
        handler: F,
    ) where
        Args: JsonSchema + DeserializeOwned + 'static,
        F: Fn(Args) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = (String, String)> + 'static,
    {
        self.register(TypedTool::new::<Args, _, _>(
            name,
            Some(description),
            handler,
        ));
    }

    /// Registers a tool function returning any `Serialize` type. Automatically serializes
    /// the return value to a JSON string and uses a standard completion summary.
    pub fn register_typed<Args, Res, F, Fut>(&mut self, name: &'static str, handler: F)
    where
        Args: JsonSchema + DeserializeOwned + 'static,
        Res: Serialize + 'static,
        F: Fn(Args) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = Res> + 'static,
    {
        self.register_fn(name, move |args: Args| {
            let fut = handler(args);
            async move {
                let res = fut.await;
                let json = serde_json::to_string(&res).unwrap_or_default();
                let summary = format!("{name} completed");
                (json, summary)
            }
        });
    }

    /// Registers a fallible tool call (e.g. from a generated `ToolClient`).
    /// Automatically derives schema, description from doc comments, serializes the Ok result to JSON,
    /// formats errors on failure, and computes a custom UI summary badge.
    pub fn register_tool_call<Args, Res, Err, F, Fut, S>(
        &mut self,
        name: &'static str,
        call: F,
        summary_fn: S,
    ) where
        Args: JsonSchema + DeserializeOwned + 'static,
        Res: Serialize + 'static,
        Err: std::fmt::Display + 'static,
        F: Fn(Args) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = Result<Res, Err>> + 'static,
        S: Fn(&Res) -> String + Send + Sync + 'static,
    {
        let summary_fn = std::sync::Arc::new(summary_fn);
        self.register_fn(name, move |args: Args| {
            let fut = call(args);
            let s_fn = summary_fn.clone();
            async move {
                match fut.await {
                    Ok(res) => {
                        let summary = s_fn(&res);
                        let json = serde_json::to_string(&res).unwrap_or_default();
                        (json, summary)
                    }
                    Err(err) => {
                        let msg = format!("Tool '{name}' error: {err}");
                        let summary = format!("{name} error");
                        (msg, summary)
                    }
                }
            }
        });
    }

    /// Registers a fallible tool call with an explicit description override and custom summary.
    pub fn register_tool_call_with_desc<Args, Res, Err, F, Fut, S>(
        &mut self,
        name: &'static str,
        description: &'static str,
        call: F,
        summary_fn: S,
    ) where
        Args: JsonSchema + DeserializeOwned + 'static,
        Res: Serialize + 'static,
        Err: std::fmt::Display + 'static,
        F: Fn(Args) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = Result<Res, Err>> + 'static,
        S: Fn(&Res) -> String + Send + Sync + 'static,
    {
        let summary_fn = std::sync::Arc::new(summary_fn);
        self.register_with_desc(name, description, move |args: Args| {
            let fut = call(args);
            let s_fn = summary_fn.clone();
            async move {
                match fut.await {
                    Ok(res) => {
                        let summary = s_fn(&res);
                        let json = serde_json::to_string(&res).unwrap_or_default();
                        (json, summary)
                    }
                    Err(err) => {
                        let msg = format!("Tool '{name}' error: {err}");
                        let summary = format!("{name} error");
                        (msg, summary)
                    }
                }
            }
        });
    }

    /// Registers a fallible tool call with automatic default summary and auto-extracted description.
    pub fn register_tool_call_simple<Args, Res, Err, F, Fut>(&mut self, name: &'static str, call: F)
    where
        Args: JsonSchema + DeserializeOwned + 'static,
        Res: Serialize + 'static,
        Err: std::fmt::Display + 'static,
        F: Fn(Args) -> Fut + Send + Sync + 'static,
        Fut: Future<Output = Result<Res, Err>> + 'static,
    {
        self.register_tool_call(name, call, move |_| format!("{name} completed"));
    }

    pub fn specs(&self) -> Vec<ToolSpec> {
        self.tools.iter().map(|t| t.spec.clone()).collect()
    }

    pub fn get(&self, name: &str) -> Option<&TypedTool> {
        self.tools.iter().find(|t| t.spec.name == name)
    }
}

impl ToolDispatcher for ToolRegistry {
    async fn execute(&self, name: &str, arguments: &str) -> (String, String) {
        if let Some(tool) = self.get(name) {
            tool.execute(arguments).await
        } else {
            let err_msg = format!("Unknown tool: {name}");
            (err_msg.clone(), err_msg)
        }
    }
}

impl ToolDispatcher for &ToolRegistry {
    async fn execute(&self, name: &str, arguments: &str) -> (String, String) {
        (*self).execute(name, arguments).await
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde::Deserialize;

    /// Search product catalog for items by query keywords
    #[derive(Debug, Deserialize, JsonSchema)]
    struct MockSearchArgs {
        /// Keyword to search
        query: String,
        /// Optional currency filter
        currency: Option<String>,
    }

    #[test]
    fn test_spec_from_schema_generation() {
        let raw = serde_json::to_value(schemars::schema_for!(MockSearchArgs)).unwrap_or_default();
        let extracted_desc = raw.get("description").and_then(|v| v.as_str());
        assert_eq!(
            extracted_desc,
            Some("Search product catalog for items by query keywords")
        );

        let spec = spec_from_schema::<MockSearchArgs>("search_products", None);
        assert_eq!(spec.name, "search_products");
        assert_eq!(
            spec.description,
            "Search product catalog for items by query keywords"
        );

        let params = spec.parameters;
        assert_eq!(params["type"], "object");
        assert!(params.get("$schema").is_none());
        assert!(params.get("title").is_none());
        assert!(params["properties"]["query"].is_object());
        assert_eq!(
            params["properties"]["query"]["description"],
            "Keyword to search"
        );
    }

    #[wstd::test]
    async fn test_tool_registry_typed_dispatch() {
        let mut registry = ToolRegistry::new();
        registry.register_fn("mock_search", |args: MockSearchArgs| async move {
            (
                format!("query:{},curr:{:?}", args.query, args.currency),
                "summary ok".to_string(),
            )
        });

        // Test valid call
        let (res, summary) = registry
            .execute("mock_search", r#"{"query": "shoes", "currency": "USD"}"#)
            .await;
        assert_eq!(res, "query:shoes,curr:Some(\"USD\")");
        assert_eq!(summary, "summary ok");

        // Test malformed call
        let (err_res, _) = registry.execute("mock_search", r#"{"bad": 123}"#).await;
        assert!(err_res.contains("Invalid arguments for tool 'mock_search'"));

        // Test unknown tool
        let (unknown_res, _) = registry.execute("no_such_tool", "{}").await;
        assert_eq!(unknown_res, "Unknown tool: no_such_tool");
    }
}
